with q as (select * from (values
('pcac-lc129-duties-01','LC nº 129/2004 — deveres','Constitui dever expresso do policial civil, nos termos do art. 100 da LC nº 129/2004:','(A) Divulgar livremente assuntos internos da unidade.\n(B) Usar a força sem moderação quando entender conveniente.\n(C) Atender as pessoas com urbanidade e representar contra ilegalidade, omissão ou abuso de poder.\n(D) Recusar toda ordem superior sem justificativa.\n(E) Utilizar bens públicos para fins particulares.','C','O art. 100 prevê atendimento com urbanidade e o dever de representar contra ilegalidade, omissão ou abuso de poder.'),
('pcac-lc129-rights-02','LC nº 129/2004 — direitos e porte de arma','Sobre o porte de arma do policial civil, assinale a alternativa correta conforme a LC nº 129/2004:','(A) É absoluto e não pode ser restringido.\n(B) O porte de inativo é automático e dispensa avaliação.\n(C) O porte pode ser restringido ou cassado nas hipóteses legais e conforme a legislação federal.\n(D) A carteira funcional não registra o porte.\n(E) O uso indevido da arma nunca gera consequência administrativa.','C','Os arts. 90 e 91 condicionam o porte à legislação e preveem restrição/cassação em situações específicas.'),
('pcac-lc129-rewards-03','LC nº 129/2004 — recompensas','Quais recompensas são expressamente previstas no art. 96 da LC nº 129/2004?','(A) Gratificação mensal, promoção automática e férias extras.\n(B) Dispensa de até cinco dias por ano por atividade fora da jornada, elogio e medalha do mérito policial.\n(C) Aumento salarial, licença-prêmio e aposentadoria especial.\n(D) Apenas elogio verbal.\n(E) Promoção por antiguidade automática.','B','O art. 96 enumera dispensa de até cinco dias por ano nas condições legais, elogio e medalha do mérito policial.'),
('pcac-lc129-groups-04','LC nº 129/2004 — transgressões','Trocar horário de serviço sem autorização expressa da autoridade hierarquicamente superior é transgressão:','(A) Do primeiro grupo.\n(B) Do segundo grupo.\n(C) Do terceiro grupo.\n(D) Do quarto grupo.\n(E) Não é transgressão.','A','O art. 101, I, classifica a permuta de horário sem autorização como transgressão do primeiro grupo.'),
('pcac-lc129-sanctions-05','LC nº 129/2004 — sanções disciplinares','Segundo os arts. 108 a 110 da LC nº 129/2004, qual associação está correta?','(A) Primeiro grupo: demissão direta.\n(B) Segundo grupo: apenas advertência.\n(C) Primeiro grupo: advertência; segundo e terceiro: suspensão; quarto: demissão, observadas as regras de reincidência.\n(D) Todos os grupos: suspensão fixa de 30 dias.\n(E) Quarto grupo: apenas advertência.','C','A lei prevê advertência para o primeiro grupo, suspensão para reincidência do primeiro e infrações do segundo/terceiro, e demissão para reincidência do terceiro e infrações do quarto.'),
('pcac-lc129-pad-06','LC nº 129/2004 — processo administrativo disciplinar','Quando é obrigatório instaurar processo administrativo disciplinar, conforme o art. 129 da LC nº 129/2004?','(A) Em qualquer atraso de poucos minutos.\n(B) Quando a infração, por sua natureza, puder determinar pena de demissão.\n(C) Somente após condenação criminal.\n(D) Apenas quando o servidor pedir.\n(E) Nunca, pois sindicância sempre substitui o PAD.','B','O art. 129 torna obrigatório o PAD quando a infração puder determinar demissão.'),
('pcac-lc526-interstice-07','LC nº 526/2026 — cessão e interstício','Como regra, o que ocorre com o interstício promocional durante a cessão ou disponibilização do policial civil a outro órgão?','(A) Continua correndo normalmente em qualquer cessão.\n(B) É contado em dobro.\n(C) Fica suspenso e retoma no primeiro dia de efetivo exercício na unidade de origem, ressalvadas as exceções legais.\n(D) É definitivamente cancelado.\n(E) Começa novamente do zero em todos os casos.','C','A LC nº 526/2026 prevê suspensão da contagem a partir da publicação do ato de cessão e retomada no retorno à unidade de origem, com exceções expressas para funções estratégicas indicadas na lei.'),
('pcac-lc526-investiture-08','LC nº 526/2026 — ingresso e formação','De acordo com a redação dada pela LC nº 526/2026 ao art. 65, § 2º, quando começa o curso específico de formação policial?','(A) Somente depois do estágio probatório.\n(B) Após um ano de exercício.\n(C) Imediatamente após o ato coletivo de investidura, sendo frequentado pelo servidor na condição de efetivo exercício.\n(D) Antes da nomeação e posse.\n(E) Apenas após aprovação em prova oral para todos os cargos.','C','A LC nº 526/2026 determina que o ato coletivo de investidura marca o início imediato do curso específico de formação, frequentado na condição de servidor em efetivo exercício.')
) as t(external_item_key,subtopic,question_text,options_text,answer,explanation))
